-- 00272 — Constats-types ISO 27001 pour l'ensemble des mesures (couverture complète).
-- Généré depuis le référentiel ISO 27001 (seed 002, source du contenu/des codes). Un
-- constat-type « minor_nc » par mesure : constat = référence à la mesure, recommandation
-- = intitulé de mise en œuvre de la mesure, risque = formulation par thème. Garde
-- d'idempotence : n'insère pas si la mesure a déjà un constat-type plateforme « minor_nc »
-- (ex. starters 00269).

insert into public.finding_templates (scope, control_id, classification, description, risks, recommendations)
