  ('A.8.34', 'Non-conformité à la mesure A.8.34 « Protection des systèmes d''information durant les tests d''audit ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Sécurité pendant les audits techniques')
) as t(code, descr, risk, reco)
join public.controls c on c.code = t.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000010')
where not exists (
  select 1 from public.finding_templates ft
  where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc'
);
